describe('Tablet Layout Switch', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('ipad-2'); // Set viewport to tablet size
    });

    it('should display the layout in a two-column grid on tablet', () => {
        cy.get('.container') // Replace with the actual container class or ID
            .should('have.class', 'two-column-grid'); // Check for the two-column grid class
    });

    it('should not display a single-column layout on tablet', () => {
        cy.get('.container') // Replace with the actual container class or ID
            .should('not.have.class', 'single-column'); // Ensure single-column class is not present
    });
});
